PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX : <https://w3id.org/DOLCE/OWL/DOLCEbasic#>

SELECT DISTINCT ?dependent ?dependentLabel
WHERE {
  ?dependent :specificallyDependsOn ?dependee .
  ?dependee rdf:type :GivenClass .
  OPTIONAL { ?dependent rdfs:label ?dependentLabel. }
}
